/*
Table with ids, dimensions, metrics and timestamps related to search.
*/ /* --------------- */ /* Union SPVS */ WITH union_spvs AS (SELECT event_properties, user_properties, id_user, id_session, id_amplitude, id_device, 'spv' AS search_rendering_type, ts_event FROM datalake_amplitude_clean.170698_search_page_viewed_events WHERE MAKE_DATE(year, month, day) /* include one more day to make sure we don't repeat id_search that start before midnight and end after. */ BETWEEN DATE_ADD(CAST('{start_date}' AS DATE), STRUCT(days_past_30 AS days_past_30) + 1 * -1) AND CAST('{end_date}' AS DATE) AND NOT GET_JSON_OBJECT(event_properties, '$.search_id') IS NULL AND NOT GET_JSON_OBJECT(event_properties, '$.search_results_list') IS NULL AND GET_JSON_OBJECT(event_properties, '$.search_results_list') <> '[]' AND GET_JSON_OBJECT(user_properties, '$.country') = 'BR' AND NOT id_user IS NULL UNION ALL SELECT event_properties, user_properties, id_user, id_session, id_amplitude, id_device, 'srpv' AS search_rendering_type, ts_event FROM datalake_amplitude_clean.170698_search_results_page_viewed_events WHERE MAKE_DATE(year, month, day) /* include one more day to make sure we don't repeat id_search that start before midnight and end after. */ BETWEEN DATE_ADD(CAST('{start_date}' AS DATE), STRUCT(days_past_30 AS days_past_30) + 1 * -1) AND CAST('{end_date}' AS DATE) AND NOT GET_JSON_OBJECT(event_properties, '$.search_id') IS NULL AND NOT GET_JSON_OBJECT(event_properties, '$.search_results_list') IS NULL AND GET_JSON_OBJECT(event_properties, '$.search_results_list') <> '[]' AND GET_JSON_OBJECT(user_properties, '$.country') = 'BR' AND NOT id_user IS NULL), duplicated_searches /* --------------- */ /* Searches */ AS (SELECT GET_JSON_OBJECT(union_spvs.event_properties, '$.search_id') AS id_search /* ids */, id_user, id_session, id_amplitude, id_device, GET_JSON_OBJECT(event_properties, '$.business_context') AS business_context /* dimensions */, GET_JSON_OBJECT(user_properties, '$.platform') AS device_type, GET_JSON_OBJECT(event_properties, '$.sort_order') AS sort_order, GET_JSON_OBJECT(event_properties, '$.copilot_session_id') AS copilot_session_id, union_spvs.ts_event /* event_timestamps */, ROW_NUMBER() OVER (PARTITION BY GET_JSON_OBJECT(union_spvs.event_properties, '$.search_id') ORDER BY ts_event, id_user /* in principle ts_event should be enough but, */ /* if there are multiple rows with different information (due to bugs) the next code makes the query deterministic */, id_session, id_amplitude, id_device, GET_JSON_OBJECT(event_properties, '$.business_context'), GET_JSON_OBJECT(user_properties, '$.platform'), GET_JSON_OBJECT(event_properties, '$.sort_order'), GET_JSON_OBJECT(event_properties, '$.copilot_session_id')) AS row_n FROM union_spvs), searches AS (SELECT DISTINCT *, CASE WHEN device_type IN ('android', 'ios') THEN 'app' WHEN device_type IN ('web_desktop', 'web_mobile') THEN 'web' ELSE 'None' END AS platform FROM duplicated_searches WHERE row_n = 1), duplicate_experiment_searches /* --------------- */ /* Experiment Searches */ AS (SELECT GET_JSON_OBJECT(union_spvs.event_properties, '$.search_id') AS id_search, experiments.experiment_name, experiments.variant_standard_name, ROW_NUMBER() OVER (PARTITION BY GET_JSON_OBJECT(union_spvs.event_properties, '$.search_id'), experiments.experiment_name ORDER BY ts_event) AS row_n FROM union_spvs INNER JOIN datalake_search.experiment_config_processed AS experiments ON experiments.variant_name = GET_JSON_OBJECT(union_spvs.user_properties, CONCAT('$.', experiments.experiment_name)) AND ((ts_event >= experiments.begin_date) AND (experiments.end_date IS NULL OR ts_event <= experiments.end_date))), experiment_searches_not_json AS (SELECT DISTINCT id_search, CONCAT('"', duplicate_experiment_searches.experiment_name, '":"', variant_standard_name, '"') AS variants FROM duplicate_experiment_searches WHERE row_n = 1), experiment_searches AS (SELECT id_search, CONCAT('', ARRAY_JOIN(COLLECT_LIST(variants), ','), '') AS variants FROM experiment_searches_not_json GROUP BY id_search), clicks /* --------------- */ /* Metrics */ /* --------------- */ /* Clicks */ AS (SELECT DISTINCT GET_JSON_OBJECT(event_properties, '$.search_id') AS id_search, ep_house_id AS id_house, 1 AS click FROM datalake_amplitude_clean.170698_listing_page_viewed_events WHERE MAKE_DATE(year, month, day) BETWEEN DATE_ADD(CAST('{start_date}' AS DATE), STRUCT(days_past_30 AS days_past_30) * -1) AND CAST('{end_date}' AS DATE) AND GET_JSON_OBJECT(event_properties, '$.from_route') = 'search_results' AND NOT GET_JSON_OBJECT(event_properties, '$.search_id') IS NULL), search_house /* --------------- */ /* Granularity Search  House */ /* --------------- */ /* Houses Rank */ AS (SELECT GET_JSON_OBJECT(event_properties, '$.search_id') AS id_search, POSEXPLODE(SPLIT(REGEXP_REPLACE(GET_JSON_OBJECT(event_properties, '$.search_results_list'), '\\[|\\]|"', ''), ',')) AS (page_position, id_house), GET_JSON_OBJECT(event_properties, '$.business_context') AS business_context, GET_JSON_OBJECT(user_properties, '$.platform') AS device_type, GET_JSON_OBJECT(event_properties, '$.view_mode') AS view_mode, search_rendering_type, ts_event FROM union_spvs), abs_position AS (SELECT id_search, id_house, FIRST(device_type) OVER (PARTITION BY id_search) AS device_type, FIRST(view_mode) OVER (PARTITION BY id_search) AS view_mode, FIRST(search_rendering_type) OVER (PARTITION BY id_search) AS search_rendering_type, FIRST(business_context) OVER (PARTITION BY id_search) AS business_context, MIN(ts_event) OVER (PARTITION BY id_search) AS ts_search, DENSE_RANK() OVER (PARTITION BY id_search ORDER BY ts_event, page_position) AS absolute_position, DENSE_RANK() OVER (PARTITION BY id_search ORDER BY ts_event) AS page_number FROM search_house), min_abs_position AS (SELECT id_search, id_house, business_context, device_type, view_mode, search_rendering_type, ts_search, MIN(absolute_position) AS absolute_position, MIN(page_number) AS page_number FROM abs_position GROUP BY id_search, id_house, business_context, device_type, view_mode, search_rendering_type, ts_search), houses_rank AS (SELECT id_search, id_house, business_context, search_rendering_type, CASE WHEN device_type IN ('android', 'ios') AND view_mode = 'map' THEN 'LTR' WHEN device_type IN ('web_desktop', 'web_mobile') AND search_rendering_type = 'spv' THEN 'LTR' ELSE 'pclick' END AS rank_model, ts_search, DENSE_RANK() OVER (PARTITION BY id_search ORDER BY absolute_position) AS absolute_position, DENSE_RANK() OVER (PARTITION BY id_search ORDER BY page_number) AS page_number, DENSE_RANK() OVER (PARTITION BY id_search, page_number ORDER BY absolute_position) AS page_position FROM min_abs_position), house_cities /* --------------- */ /* Houses Cities */ AS (SELECT id AS id_house, LAST(city) AS city, LAST(is_classified) AS is_classified FROM wonka.house_main GROUP BY id), exploded_houses /* --------------- */ /* Exploded Houses */ AS (SELECT houses_rank.id_search, houses_rank.id_house, house_cities.city, house_cities.is_classified, houses_rank.search_rendering_type, houses_rank.rank_model, houses_rank.absolute_position, houses_rank.page_number, houses_rank.page_position, MAX(houses_published.ts_house_published) AS ts_house_published, CAST(DATEDIFF(TO_DATE(FIRST(houses_rank.ts_search)), TO_DATE(MAX(houses_published.ts_house_published))) AS INT) AS listing_age FROM houses_rank LEFT JOIN datalake_search.house_publication_dates AS houses_published ON houses_rank.id_house = houses_published.id_house AND houses_rank.business_context = houses_published.business_context AND houses_published.ts_house_published <= houses_rank.ts_search LEFT JOIN house_cities ON houses_rank.id_house = house_cities.id_house GROUP BY houses_rank.id_search, houses_rank.id_house, house_cities.city, house_cities.is_classified, houses_rank.search_rendering_type, houses_rank.rank_model, houses_rank.absolute_position, houses_rank.page_number, houses_rank.page_position) /* --------------- */ /* Final Query */ SELECT TO_JSON(NAMED_STRUCT('id_search', searches.id_search, 'id_house', exploded_houses.id_house, 'id_user', searches.id_user, 'id_session', searches.id_session, 'id_amplitude', searches.id_amplitude, 'id_device', searches.id_device, 'id_agent', COALESCE(rent_flow.id_agent, sale_flow.id_agent), 'copilot_session_id', searches.copilot_session_id)) AS ids /* ids */, TO_JSON(NAMED_STRUCT('business_context', searches.business_context, 'city', exploded_houses.city, 'device_type', searches.device_type, 'platform', searches.platform, 'sort_order', searches.sort_order, 'search_rendering_type', exploded_houses.search_rendering_type, 'rank_model', exploded_houses.rank_model, 'absolute_position', exploded_houses.absolute_position, 'page_number', exploded_houses.page_number, 'page_position', exploded_houses.page_position, 'listing_age', exploded_houses.listing_age, 'is_classified', exploded_houses.is_classified, 'is_outlier_user', CASE WHEN NOT COALESCE(rent_outlier_users.id_user, sale_outlier_users.id_user) IS NULL THEN 1 ELSE 0 END, 'visit_creation_origin', COALESCE(rent_flow.visit_creation_origin, sale_flow.visit_creation_origin))) AS dimensions /* dimensions */, COALESCE(variants, '') AS variants /* experimentation */, TO_JSON(NAMED_STRUCT('search', 1, 'click', COALESCE(clicks.click, 0), 'visit_booked', CASE WHEN COALESCE(rent_flow.ts_visit_booked, sale_flow.ts_visit_booked) >= searches.ts_event THEN 1 ELSE 0 END, 'visit_completed', CASE WHEN COALESCE(rent_flow.ts_visit_completed, sale_flow.ts_visit_completed) >= searches.ts_event THEN 1 ELSE 0 END, 'offer', CASE WHEN COALESCE(rent_flow.ts_offer, sale_flow.ts_offer) >= searches.ts_event THEN 1 ELSE 0 END, 'direct_offer', CASE WHEN rent_flow.ts_direct_offer >= searches.ts_event THEN 1 ELSE 0 END, 'offer_submitted', CASE WHEN rent_flow.ts_offer_submitted >= searches.ts_event THEN 1 ELSE 0 END, 'offer_approved', CASE WHEN COALESCE(rent_flow.ts_offer_approved, sale_flow.ts_offer_approved) >= searches.ts_event THEN 1 ELSE 0 END, 'contract_signed', CASE WHEN COALESCE(rent_flow.ts_contract_signed, sale_flow.ts_contract_signed) >= searches.ts_event THEN 1 ELSE 0 END, 'relevant_search', MAX(CASE WHEN (clicks.click = 1 OR COALESCE(rent_flow.ts_offer, sale_flow.ts_offer) >= searches.ts_event OR COALESCE(rent_flow.ts_visit_completed, sale_flow.ts_visit_completed) >= searches.ts_event OR COALESCE(rent_flow.ts_contract_signed, sale_flow.ts_contract_signed) >= searches.ts_event) THEN 1 ELSE 0 END) OVER (PARTITION BY searches.id_search))) AS metrics /* metrics */, TO_JSON(NAMED_STRUCT('ts_search', searches.ts_event, 'ts_house_published', exploded_houses.ts_house_published, 'ts_visit_booked', COALESCE(rent_flow.ts_visit_booked, sale_flow.ts_visit_booked), 'ts_visit_completed', COALESCE(rent_flow.ts_visit_completed, sale_flow.ts_visit_completed), 'ts_offer', COALESCE(rent_flow.ts_offer, sale_flow.ts_offer), 'ts_direct_offer', rent_flow.ts_direct_offer, 'ts_offer_submitted', rent_flow.ts_offer_submitted, 'ts_offer_approved', COALESCE(rent_flow.ts_offer_approved, sale_flow.ts_offer_approved), 'ts_contract_signed', COALESCE(rent_flow.ts_contract_signed, sale_flow.ts_contract_signed))) AS timestamps /* timestamps */, searches.ts_event, CAST(searches.ts_event AS DATE) AS date, YEAR(TO_DATE(searches.ts_event)) AS year, MONTH(TO_DATE(searches.ts_event)) AS month, DAY(TO_DATE(searches.ts_event)) AS day, WEEKOFYEAR(TO_DATE(searches.ts_event)) AS week FROM searches LEFT JOIN experiment_searches ON searches.id_search = experiment_searches.id_search LEFT JOIN exploded_houses ON searches.id_search = exploded_houses.id_search LEFT JOIN clicks ON searches.id_search = clicks.id_search AND exploded_houses.id_house = clicks.id_house LEFT JOIN datalake_search.rent_flow_past_30_days AS rent_flow ON exploded_houses.id_house = rent_flow.id_house AND searches.id_user = rent_flow.id_user AND searches.business_context = 'rent' LEFT JOIN datalake_search.sale_flow_past_30_days AS sale_flow ON exploded_houses.id_house = sale_flow.id_house AND searches.id_user = sale_flow.id_user AND searches.business_context = 'sale' LEFT JOIN datalake_search.rent_outlier_users_past_30_days AS rent_outlier_users ON searches.id_user = rent_outlier_users.id_user AND searches.business_context = 'rent' LEFT JOIN datalake_search.sale_outlier_users_past_30_days AS sale_outlier_users ON searches.id_user = sale_outlier_users.id_user AND searches.business_context = 'sale' WHERE searches.ts_event BETWEEN DATE_ADD(CAST('{start_date}' AS DATE), STRUCT(days_past_30 AS days_past_30) * -1) AND CAST('{end_date}' AS DATE)